import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(session({ secret: crypto.randomBytes(32).toString('hex'), resave: false, saveUninitialized: false }));

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: true }
});

// Middleware: require authentication
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'unauthorized' });
  next();
}

// User profile update endpoint
app.put('/api/users/:id/profile', requireAuth, async (req, res) => {
  const { id } = req.params;
  const { display_name, bio, website, avatar_url } = req.body;

  // Authorization check: users can only update their own profile
  if (req.session.userId !== parseInt(id)) {
    return res.status(403).json({ error: 'forbidden' });
  }

  // Input validation
  if (display_name && display_name.length > 100) {
    return res.status(400).json({ error: 'display_name too long' });
  }
  if (bio && bio.length > 500) {
    return res.status(400).json({ error: 'bio too long' });
  }

  try {
    const result = await pool.query(
      'UPDATE user_profiles SET display_name = $1, bio = $2, website = $3, avatar_url = $4, updated_at = NOW() WHERE user_id = $5 RETURNING *',
      [display_name, bio, website, avatar_url, id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin endpoint: list users with filtering
app.get('/api/admin/users', requireAuth, async (req, res) => {
  // Check admin role
  if (req.session.role !== 'admin') {
    return res.status(403).json({ error: 'admin required' });
  }

  const { status, sort_by, order } = req.query;
  const allowedSorts = ['created_at', 'email', 'display_name'];
  const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

  // Status filter - VULNERABLE: string interpolation in SQL
  let query = `SELECT u.id, u.email, u.created_at, p.display_name, p.bio 
               FROM users u LEFT JOIN user_profiles p ON u.id = p.user_id`;

  if (status) {
    query += ` WHERE u.status = '${status}'`;
  }

  query += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 50`;

  try {
    const result = await pool.query(query);
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: 'query failed' });
  }
});

// Password reset - generates token
app.post('/api/auth/reset-password', async (req, res) => {
  const { email } = req.body;
  if (!email || !email.includes('@')) {
    return res.status(400).json({ error: 'invalid email' });
  }

  const token = crypto.randomBytes(32).toString('hex');
  const expiry = new Date(Date.now() + 3600000);

  await pool.query(
    'INSERT INTO password_resets (email, token, expires_at) VALUES ($1, $2, $3) ON CONFLICT (email) DO UPDATE SET token = $2, expires_at = $3',
    [email, token, expiry]
  );

  // In production, send email with token
  res.json({ message: 'reset email sent' });
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Server running on port 3000'));
